// Parse and validate location input
const body = $input.first().json.body || $input.first().json;

const latitude = parseFloat(body.latitude || body.lat);
const longitude = parseFloat(body.longitude || body.lon || body.lng);
const locationName = body.location_name || body.city || `${latitude},${longitude}`;
const commodity = body.commodity || null;
const forecastDays = parseInt(body.forecast_days || 7);

if (isNaN(latitude) || isNaN(longitude)) {
  throw new Error('Latitude dan longitude wajib disertakan dan harus berupa angka');
}

// Validate Indonesian bounds approximately
if (latitude < -11 || latitude > 6 || longitude < 95 || longitude > 141) {
  throw new Error('Koordinat di luar wilayah Indonesia');
}

return [{
  json: {
    latitude: latitude,
    longitude: longitude,
    location_name: locationName,
    commodity: commodity,
    forecast_days: Math.min(forecastDays, 16),
    request_id: `wx_${Date.now()}`,
    start_time: Date.now()
  }
}];

// Parse combined weather + climate data
const items = $input.all();
const validatorData = $('✅ Location Validator').item.json;

let weatherData = {};
let climateData = {};

for (const item of items) {
  if (item.json.list) {
    // OpenWeatherMap forecast
    const forecasts = item.json.list || [];
    const daily = {};
    for (const f of forecasts) {
      const day = new Date(f.dt * 1000).toISOString().split('T')[0];
      if (!daily[day]) {
        daily[day] = {
          date: day,
          temp_min: f.main.temp_min,
          temp_max: f.main.temp_max,
          temp_avg: f.main.temp,
          humidity: f.main.humidity,
          rainfall_mm: (f.rain?.['3h'] || 0) * 8, // 3h to 24h estimate
          weather_desc: f.weather[0]?.description || '',
          weather_icon: f.weather[0]?.icon || '',
          wind_speed_ms: f.wind?.speed || 0
        };
      }
    }
    weatherData = {
      city: item.json.city?.name || validatorData.location_name,
      country: item.json.city?.country || 'ID',
      daily_forecast: Object.values(daily).slice(0, validatorData.forecast_days)
    };
  } else if (item.json.properties) {
    // NASA POWER format
    const params = item.json.properties.parameter || {};
    const t2m = params.T2M || {};
    const prec = params.PRECTOTCORR || {};
    const rh2m = params.RH2M || {};

    const dates = Object.keys(t2m);
    const avgTemp = dates.reduce((s, d) => s + (t2m[d] || 0), 0) / dates.length;
    const totalRainfall = dates.reduce((s, d) => s + (prec[d] || 0), 0);
    const avgHumidity = dates.reduce((s, d) => s + (rh2m[d] || 0), 0) / dates.length;

    climateData = {
      period_days: dates.length,
      avg_temperature_c: Math.round(avgTemp * 10) / 10,
      total_rainfall_mm: Math.round(totalRainfall * 10) / 10,
      avg_humidity_pct: Math.round(avgHumidity * 10) / 10,
      source: 'NASA POWER'
    };
  }
}

// Planting calendar generation based on climate
function getPlantingCalendar(climate, commodity) {
  const month = new Date().getMonth() + 1;
  const isWetSeason = climate.total_rainfall_mm > 100; // simplified

  const recommendations = [];

  if (isWetSeason) {
    recommendations.push({ crop: 'Padi', suitability: 'Sangat Baik', reason: 'Musim hujan ideal untuk padi' });
    recommendations.push({ crop: 'Jagung', suitability: 'Baik', reason: 'Cukup air untuk pertumbuhan' });
    recommendations.push({ crop: 'Cabai', suitability: 'Cukup', reason: 'Perlu drainase baik' });
  } else {
    recommendations.push({ crop: 'Singkong', suitability: 'Sangat Baik', reason: 'Toleran kekeringan' });
    recommendations.push({ crop: 'Jagung', suitability: 'Cukup', reason: 'Butuh irigasi tambahan' });
    recommendations.push({ crop: 'Kacang Tanah', suitability: 'Baik', reason: 'Cocok musim kemarau' });
  }

  return {
    current_season: isWetSeason ? 'Musim Hujan' : 'Musim Kemarau',
    month: month,
    planting_recommendations: recommendations,
    next_review_date: new Date(Date.now() + 30 * 86400000).toISOString().split('T')[0]
  };
}

const plantingCalendar = getPlantingCalendar(climateData, validatorData.commodity);

return [{
  json: {
    location: {
      name: validatorData.location_name,
      latitude: validatorData.latitude,
      longitude: validatorData.longitude
    },
    weather_forecast: weatherData,
    climate_summary: climateData,
    planting_calendar: plantingCalendar,
    request_id: validatorData.request_id,
    processing_time_ms: Date.now() - validatorData.start_time
  }
}];

