const weatherData = $('🗂️ Parse Climate Data').item.json;
const geminiResponse = $input.first().json;

const aiRecommendation = geminiResponse?.candidates?.[0]?.content?.parts?.[0]?.text
  || 'Rekomendasi AI tidak tersedia saat ini.';

return [{
  json: {
    success: true,
    ...weatherData,
    ai_farming_recommendation: aiRecommendation,
    metadata: {
      engine: 'agrisensa-weather-v2',
      data_sources: ['OpenWeatherMap', 'NASA POWER', 'Gemini AI'],
      workflow: 'WF-05',
      timestamp: new Date().toISOString()
    }
  }
}];
